export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

/** An offer is lapsed from the instant its window closes, not after it. */
function isLapsed(handover: OwnershipHandover, now: number): boolean {
  return Date.parse(handover.expiresAt) <= now;
}

/**
 * Only the recorded owner may offer or withdraw. Holding the owner role is
 * not enough, so this is checked against `organization.ownerId` as well.
 */
function assertRecordedOwner(
  actor: Actor,
  organization: Organization,
  action: PermissionAction,
): void {
  if (actor.userId === organization.ownerId) return;

  throw new PermissionDeniedError(action, {
    allowed: false,
    action,
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

/**
 * The offer the caller is answering. Only the offered member can answer, and
 * a lapsed offer is refused as `expired` rather than treated as open.
 */
async function answerableOffer(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const pending = await ownershipHandoverRepo.findPending(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  if (isLapsed(pending, Date.now())) {
    throw new OwnershipHandoverError("expired");
  }

  return pending;
}

/**
 * Offers the workspace to another active member. The offered member is the
 * only one alerted, and only one offer may be open at a time.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:transfer_ownership", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, organization, "org:transfer_ownership");

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  await ownershipHandoverRepo.expireLapsedPending(orgId, createdAt);

  if (await ownershipHandoverRepo.findPending(orgId)) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await ownershipHandoverRepo.insertPending({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt,
    expiresAt: toIsoTimestamp(new Date(now.getTime() + OWNERSHIP_OFFER_TTL_MS)),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Ownership of a workspace was offered to you",
    body: `Accept to become the owner of ${organization.name}`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes over. The incoming owner is promoted before the
 * outgoing one is demoted, so the workspace never lacks an owner. Every role
 * change is announced as a manual one, and the handover itself is announced
 * as `organization.ownership_transferred`, all on behalf of the accepting member.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const offer = await answerableOffer(actor, orgId);

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const incoming = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );
  const outgoing = await memberRepo.findMember(orgId, organization.ownerId);
  const stamp = toIsoTimestamp(new Date());

  if (incoming.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: incoming.role,
      to: promoted.role,
    });
  }

  if (outgoing !== null && outgoing.role === "owner") {
    const steppedDown = await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: steppedDown.id,
      from: outgoing.role,
      to: steppedDown.role,
    });
  }

  const updated = await orgRepo.setOwner(orgId, actor.userId);
  await ownershipHandoverRepo.resolvePending(orgId, offer.id, "accepted", stamp);

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: organization.ownerId,
    toUserId: actor.userId,
  });

  return updated;
}

/** The offered member turns the offer down; afterwards the owner may offer again. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const offer = await answerableOffer(actor, orgId);

  return ownershipHandoverRepo.resolvePending(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The recorded owner withdraws an open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:transfer_ownership", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, organization, "org:transfer_ownership");

  const pending = await ownershipHandoverRepo.findPending(orgId);
  if (!pending || isLapsed(pending, Date.now())) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return ownershipHandoverRepo.resolvePending(
    orgId,
    pending.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

/** The open offer for the workspace, visible to every member; `null` when none is open. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const pending = await ownershipHandoverRepo.findPending(orgId);
  if (!pending || isLapsed(pending, Date.now())) return null;

  return pending;
}

